// Spec section 3 formats, byte for byte against contracts/game/tests/vectors.json (generated by the
// lead's Python script, an independent implementation). Key values are also pinned inline.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  botPreimage, chatTag, commitmentOf, handleOf, humanPreimage, normalizeSigners, promptHash, secretHash, skinMessage, seatSeed,
} from '../src/formats.js';
import { gamertag, WORDS } from '../../shared/names.js';
import { sha256Hex } from '../src/crypto.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const vectorsFile = path.resolve(here, '../../contracts/game/tests/vectors.json');
const V = JSON.parse(fs.readFileSync(vectorsFile, 'utf8'));

test('secret hash', () => {
  assert.equal(secretHash(V.secret), V.secret_hash);
  assert.equal(secretHash('ab'.repeat(32)), '271a413bd339c5709fdceaec41f14f11e9fbfb5042d72d331c65f32b284cd09a');
});

test('prompt hash', () => {
  assert.equal(promptHash(V.bot.prompt), V.bot.prompt_hash);
});

test('bot commitment preimage and hash', () => {
  const pre = botPreimage({
    roundId: V.round_id, characterId: V.bot.character_id, model: V.bot.model, promptHash: V.bot.prompt_hash,
    signers: V.bot.signers, payout: V.bot.payout, salt: V.bot.salt,
  });
  assert.equal(pre, V.bot.preimage);
  assert.equal(commitmentOf(pre), V.bot.commitment);
  assert.equal(commitmentOf(pre), '80bcfe82fa447bb6b88d41aecd4c9406c9457f08d5c4bb041a37802d41efc868');
});

test('signers are lowercased, sorted and deduplicated before joining', () => {
  assert.deepEqual(normalizeSigners(['0xBB', '0xaa', '0xbb']), ['0xaa', '0xbb']);
  const a = botPreimage({ roundId: 7, characterId: 'c', model: 'm', promptHash: 'p', signers: ['0xB2', '0xa1'], payout: 'x', salt: 's' });
  assert.equal(a, 'realsies:v1|bot|7|c|m|p|0xa1,0xb2|x|s');
});

test('human commitment preimage and hash', () => {
  const pre = humanPreimage({ roundId: V.round_id, characterId: V.human.character_id, account: V.human.account, payout: V.human.payout, salt: V.human.salt });
  assert.equal(pre, V.human.preimage);
  assert.equal(commitmentOf(pre), V.human.commitment);
  assert.equal(commitmentOf(pre), '057c6966ecbc6279bb548318b77380b6b1ff6784144c09e1e0c1e8b256ff885c');
});

test('handles per viewer per character', () => {
  const h = (cid: string, viewer: string) => handleOf(V.round_id, cid, viewer, V.secret);
  assert.equal(h(V.bot.character_id, 'alice.testnet'), V.handles.alice_bot);
  assert.equal(h(V.bot.character_id, 'bob.testnet'), V.handles.bob_bot);
  assert.equal(h(V.bot.character_id, 'carol.testnet'), V.handles.carol_bot);
  assert.equal(h(V.human.character_id, 'carol.testnet'), V.handles.carol_human);
  assert.equal(h(V.human.character_id, 'erin.testnet'), V.handles.erin_human);
  assert.equal(V.handles.alice_bot, '0db3dce047ef93d69bb932b2d0bd4e5b0477a2c35a7093547a942cdfa9d1792e');
});

test('chat tag and skin message (spec 1.1) match the vector requests', () => {
  for (const viewer of ['alice.testnet', 'bob.testnet']) {
    const tag = chatTag(handleOf(V.round_id, V.bot.character_id, viewer, V.secret));
    assert.equal(tag.length, 16);
    const req = JSON.parse(V.bot.proofs[viewer].request);
    assert.equal(req.messages[1].role, 'system');
    assert.equal(req.messages[1].content, skinMessage('RedFox435', tag));
  }
  assert.equal(
    skinMessage('RedFox435', '0db3dce047ef93d6'),
    'Your gamertag in this chat is RedFox435; the game generated it, you did not choose it. Game record: 0db3dce047ef93d6.',
  );
});

test('seat seeds are deterministic per viewer, round, level and seat', () => {
  const a = seatSeed('k', 3, 'ana.realsies.testnet', 2, 4);
  assert.equal(a, seatSeed('k', 3, 'ana.realsies.testnet', 2, 4));
  assert.notEqual(a, seatSeed('k', 3, 'ben.realsies.testnet', 2, 4));
  assert.notEqual(a, seatSeed('k', 3, 'ana.realsies.testnet', 2, 5));
  assert.match(a, /^[0-9a-f]{64}$/);
  assert.match(gamertag(a), /^[A-Z][a-z]+\d{2,3}$/);
});

test('gamertags v2: one word plus 2 or 3 digits, deterministic, no bot words', () => {
  const words = new Set(WORDS);
  assert.ok(words.size >= 100 && words.size === WORDS.length, 'word list without duplicates');
  for (const w of WORDS) {
    assert.match(w, /^[A-Z][a-z]+$/, `one capitalised word: ${w}`);
    assert.ok(!/^(bot|robot|droid|android|cyborg|ai|gpt|llm|model|machine|cpu|chip)$/i.test(w), `no bot hint: ${w}`);
  }
  let two = 0;
  const seen = new Set<string>();
  const N = 3000;
  for (let i = 0; i < N; i++) {
    const seed = sha256Hex(`names|${i}`);
    const g = gamertag(seed);
    assert.equal(gamertag(seed), g, 'deterministic');
    const m = /^([A-Z][a-z]+)(\d{2,3})$/.exec(g);
    assert.ok(m, `format: ${g}`);
    assert.ok(words.has(m![1]), `word from the list: ${g}`);
    const n = Number(m![2]);
    if (m![2].length === 2) {
      two++;
      assert.ok(n >= 10 && n <= 99, g);
    } else assert.ok(n >= 100 && n <= 999, g);
    seen.add(m![1]);
  }
  assert.ok(Math.abs(two / N - 86 / 256) < 0.04, `about a third have two digits (${two} of ${N})`);
  assert.ok(seen.size > WORDS.length * 0.9, `words spread across the list (${seen.size} of ${WORDS.length})`);
  assert.equal(gamertag('not hex at all'), gamertag('not hex at all'));
});
